"""
    [1/a^2, 0, 1/b^2, 0, 0, -1]
    """
def get_ellipse_equation_coefficient_by_simplest_focus_add(
    x1: Any, y1: Any, x2: Any, y2: Any, add: Any
) -> object {
    if (y1 == 0) {
        a = add / 2;
        aa = a * a;
        c = abs(x1);
        bb = aa - (c ** 2);
        return [(1 / aa), 0, (1 / bb), 0, 0, -1];
    }
    b = add / 2;
    bb = b * b;
    c = abs(y1);
    aa = bb - (c ** 2);
    return [(1 / aa), 0, (1 / bb), 0, 0, -1];
}

""" Convert the stack dumps and sample counts into the flamegraph format.

    Return a list of lines.
    """
def to_flamegraph(stacks: Any, counts: Any) -> object {
    lines = [];
    for id in counts {
        stack = ";".join(reversed(stacks[id]));
        count = counts[id];
        lines.append('{0} {1}'.format(stack, count));
    }
    return lines;
}

"""Extracts the sprreadsheet id from an url."""
def extract_spreadsheet_id(string: Any) -> object {
    if ("/edit" in string) {
        string = string.split("/edit")[0];
    }
    if ("/" in string) {
        string = string.rstrip("/");
        string = string.split("/")[-1];
        string = string.split("&")[0];
        string = string.split("#")[0];
    }
    return string;
}

